-- Phase 6B completes negotiation and contracts without rewriting the deployed Phase 6A schema.
-- All financial records created here are plans/commitments: this migration never moves cash or recognises revenue.

ALTER TABLE public.festival_sponsor_invitations ADD COLUMN IF NOT EXISTS sponsor_source text;
ALTER TABLE public.festival_sponsor_invitations ADD CONSTRAINT festival_sponsor_invitation_source_check CHECK (sponsor_source IS NULL OR sponsor_source IN ('player_company','npc_company','admin_sponsor')) NOT VALID;
UPDATE public.festival_sponsor_invitations SET sponsor_source=CASE WHEN company_id IS NOT NULL THEN 'player_company' WHEN npc_sponsor_id IS NOT NULL THEN 'npc_company' ELSE 'admin_sponsor' END WHERE sponsor_source IS NULL;
ALTER TABLE public.festival_sponsor_invitations ALTER COLUMN sponsor_source SET NOT NULL;
ALTER TABLE public.festival_sponsor_invitations VALIDATE CONSTRAINT festival_sponsor_invitation_source_check;
ALTER TABLE public.festival_sponsor_proposals ADD COLUMN IF NOT EXISTS prospect_id uuid REFERENCES public.festival_sponsor_prospects(id);
ALTER TABLE public.festival_sponsor_proposal_revisions ADD COLUMN IF NOT EXISTS in_kind_snapshot jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.festival_sponsor_proposal_revisions ADD COLUMN IF NOT EXISTS response_deadline timestamptz;
ALTER TABLE public.festival_financial_receivables ADD COLUMN IF NOT EXISTS planned_due_at timestamptz;
ALTER TABLE public.festival_financial_receivables ADD COLUMN IF NOT EXISTS contribution_category text;
ALTER TABLE public.festival_financial_receivables ADD COLUMN IF NOT EXISTS quantity integer;
ALTER TABLE public.festival_financial_receivables ADD COLUMN IF NOT EXISTS delivery_start timestamptz;
ALTER TABLE public.festival_financial_receivables ADD COLUMN IF NOT EXISTS delivery_end timestamptz;
CREATE UNIQUE INDEX IF NOT EXISTS festival_sponsor_active_invitation ON public.festival_sponsor_invitations(festival_sponsorship_plan_id,coalesce(company_id,npc_sponsor_id,admin_sponsor_id)) WHERE status IN ('sent','viewed','interested');
CREATE UNIQUE INDEX IF NOT EXISTS festival_sponsor_contract_cash_receivable ON public.festival_financial_receivables(sponsor_contract_id) WHERE source_type='sponsor_contract_cash';

CREATE OR REPLACE FUNCTION public._festival_sponsor_company_authorised(p_company uuid,p_actor uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT p_actor IS NOT NULL AND EXISTS(SELECT 1 FROM public.companies c LEFT JOIN public.company_employees e ON e.company_id=c.id AND e.profile_id=p_actor AND e.status='active' WHERE c.id=p_company AND c.status='active' AND (c.owner_id=auth.uid() OR lower(coalesce(e.role,'')) IN ('ceo','manager','marketing_manager'))) $$;
CREATE OR REPLACE FUNCTION public._festival_sponsorship_authorised(p_festival uuid,p_actor uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT public._festival_operations_authorised(p_festival,p_actor) $$;

CREATE OR REPLACE FUNCTION public._festival_sponsorship_begin_action(p_company uuid,p_action text,p_target uuid,p_key uuid,p_payload jsonb) RETURNS public.festival_sponsorship_requests
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE q public.festival_sponsorship_requests%ROWTYPE; a uuid:=public._caller_profile_id(); h text:=encode(digest(jsonb_strip_nulls(p_payload)::text,'sha256'),'hex'); BEGIN IF a IS NULL OR p_key IS NULL THEN RAISE EXCEPTION 'festival_sponsorship_forbidden' USING ERRCODE='P0001'; END IF; SELECT * INTO q FROM public.festival_sponsorship_requests WHERE actor_profile_id=a AND action=p_action AND target_id=p_target AND idempotency_key=p_key FOR UPDATE; IF FOUND THEN IF q.payload_hash<>h THEN RAISE EXCEPTION 'festival_sponsorship_idempotency_conflict' USING ERRCODE='P0001'; END IF; RETURN q; END IF; INSERT INTO public.festival_sponsorship_requests(festival_company_id,actor_profile_id,action,target_id,idempotency_key,payload_hash) VALUES(p_company,a,p_action,p_target,p_key,h) RETURNING * INTO q; RETURN q; END $$;
CREATE OR REPLACE FUNCTION public._festival_sponsorship_finish_action(p_request uuid,p_company uuid,p_entity jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE o jsonb; BEGIN o:=jsonb_build_object('entity',p_entity,'sponsorship',public._festival_sponsorship_result(p_company),'communications','[]'::jsonb); UPDATE public.festival_sponsorship_requests SET status='succeeded',result=o,completed_at=now() WHERE id=p_request; RETURN o; END $$;
CREATE OR REPLACE FUNCTION public._festival_sponsorship_audit(p_request uuid,p_company uuid,p_type text,p_entity uuid,p_event text,p_old text,p_new text,p_version int,p_metadata jsonb DEFAULT '{}') RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ INSERT INTO public.festival_sponsorship_audit(festival_company_id,actor_profile_id,entity_type,entity_id,event_type,previous_state,new_state,version,metadata,request_id) VALUES(p_company,public._caller_profile_id(),p_type,p_entity,p_event,p_old,p_new,p_version,p_metadata,p_request) ON CONFLICT(request_id,event_type) DO NOTHING $$;
CREATE OR REPLACE FUNCTION public._festival_sponsorship_validate_inventory(p_plan uuid,p_package uuid,p_inventory jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE x jsonb; i public.festival_sponsorship_inventory%ROWTYPE; qty int; BEGIN FOR x IN SELECT * FROM jsonb_array_elements(coalesce(p_inventory,'[]')) LOOP qty:=coalesce((x->>'quantity')::int,1); SELECT si.* INTO i FROM public.festival_sponsorship_inventory si JOIN public.festival_sponsorship_package_inventory pi ON pi.inventory_id=si.id WHERE si.id=(x->>'inventoryId')::uuid AND si.festival_sponsorship_plan_id=p_plan AND pi.package_id=p_package FOR UPDATE; IF NOT FOUND OR i.status='archived' OR qty<=0 OR i.quantity_reserved+i.quantity_contracted+qty>i.quantity_total THEN RAISE EXCEPTION 'festival_sponsor_inventory_unavailable' USING ERRCODE='P0001'; END IF; END LOOP; END $$;
CREATE OR REPLACE FUNCTION public._festival_sponsorship_validate_exclusivity(p_plan uuid,p_proposal uuid,p_exclusivity jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE k text:=nullif(p_exclusivity->>'key',''); BEGIN IF k IS NOT NULL AND EXISTS(SELECT 1 FROM public.festival_sponsor_contracts c WHERE c.festival_sponsorship_plan_id=p_plan AND c.status NOT IN('cancelled','festival_cancelled') AND c.accepted_proposal_id<>p_proposal AND coalesce(c.exclusivity_snapshot->>'key','')=k) THEN RAISE EXCEPTION 'festival_sponsor_exclusivity_conflict' USING ERRCODE='P0001'; END IF; END $$;

CREATE OR REPLACE FUNCTION public.open_festival_sponsor_applications(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();c uuid:=(p_payload->>'festivalCompanyId')::uuid;p public.festival_sponsorship_plans%ROWTYPE;q public.festival_sponsorship_requests%ROWTYPE; BEGIN SELECT * INTO p FROM public.festival_sponsorship_plans WHERE festival_company_id=c FOR UPDATE; IF NOT public._festival_sponsorship_authorised(c,a) THEN RAISE EXCEPTION 'festival_sponsorship_forbidden' USING ERRCODE='P0001'; END IF;q:=public._festival_sponsorship_begin_action(c,'open_festival_sponsor_applications',p.id,p_idempotency_key,p_payload);IF q.status='succeeded' THEN RETURN q.result;END IF;IF p.planning_version<>(p_payload->>'expectedVersion')::int THEN RAISE EXCEPTION 'festival_sponsorship_plan_stale' USING ERRCODE='P0001';END IF;IF p.application_mode NOT IN('applications_only','hybrid') OR p.public_applications_open_at IS NULL OR p.public_applications_close_at<=greatest(now(),p.public_applications_open_at) OR NOT EXISTS(SELECT 1 FROM public.festival_operations_plans o WHERE o.id=p.operations_plan_id AND o.status='ready_for_sponsorship') OR NOT EXISTS(SELECT 1 FROM public.festival_sponsorship_packages x WHERE x.festival_sponsorship_plan_id=p.id AND x.status='active') OR NOT EXISTS(SELECT 1 FROM public.festival_sponsorship_inventory i WHERE i.festival_sponsorship_plan_id=p.id AND i.status<>'archived') THEN RAISE EXCEPTION 'festival_sponsorship_not_ready' USING ERRCODE='P0001';END IF;UPDATE public.festival_sponsorship_plans SET status='applications_open',planning_version=planning_version+1,updated_at=now() WHERE id=p.id RETURNING * INTO p;PERFORM public._festival_sponsorship_audit(q.id,c,'sponsorship_plan',p.id,'applications_opened',NULL,p.status,p.planning_version);RETURN public._festival_sponsorship_finish_action(q.id,c,to_jsonb(p));END $$;
CREATE OR REPLACE FUNCTION public.close_festival_sponsor_applications(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();c uuid:=(p_payload->>'festivalCompanyId')::uuid;p public.festival_sponsorship_plans%ROWTYPE;q public.festival_sponsorship_requests%ROWTYPE;BEGIN SELECT * INTO p FROM public.festival_sponsorship_plans WHERE festival_company_id=c FOR UPDATE;IF NOT public._festival_sponsorship_authorised(c,a) THEN RAISE EXCEPTION 'festival_sponsorship_forbidden' USING ERRCODE='P0001';END IF;q:=public._festival_sponsorship_begin_action(c,'close_festival_sponsor_applications',p.id,p_idempotency_key,p_payload);IF q.status='succeeded' THEN RETURN q.result;END IF;IF p.status<>'applications_open' OR p.planning_version<>(p_payload->>'expectedVersion')::int THEN RAISE EXCEPTION 'festival_sponsorship_plan_stale' USING ERRCODE='P0001';END IF;UPDATE public.festival_sponsorship_plans SET status='proposals_in_progress',public_applications_close_at=least(public_applications_close_at,now()),planning_version=planning_version+1,updated_at=now() WHERE id=p.id RETURNING * INTO p;PERFORM public._festival_sponsorship_audit(q.id,c,'sponsorship_plan',p.id,'applications_closed','applications_open',p.status,p.planning_version);RETURN public._festival_sponsorship_finish_action(q.id,c,to_jsonb(p));END $$;

CREATE OR REPLACE FUNCTION public.submit_festival_sponsor_application(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();c uuid:=(p_payload->>'festivalCompanyId')::uuid;co uuid:=(p_payload->>'sponsorCompanyId')::uuid;p public.festival_sponsorship_plans%ROWTYPE;pk public.festival_sponsorship_packages%ROWTYPE;x public.festival_sponsor_applications%ROWTYPE;q public.festival_sponsorship_requests%ROWTYPE;ink bigint:=coalesce((SELECT sum(greatest(0,(j->>'quantity')::int)*greatest(0,(j->>'catalogueUnitMinor')::bigint)) FROM jsonb_array_elements(coalesce(p_payload->'proposedInKindItems','[]')) j),0);BEGIN SELECT * INTO p FROM public.festival_sponsorship_plans WHERE festival_company_id=c FOR UPDATE;SELECT * INTO pk FROM public.festival_sponsorship_packages WHERE id=(p_payload->>'packageId')::uuid AND festival_sponsorship_plan_id=p.id;IF NOT public._festival_sponsor_company_authorised(co,a) THEN RAISE EXCEPTION 'festival_sponsor_company_forbidden' USING ERRCODE='P0001';END IF;q:=public._festival_sponsorship_begin_action(c,'submit_festival_sponsor_application',co,p_idempotency_key,p_payload);IF q.status='succeeded' THEN RETURN q.result;END IF;IF p.status<>'applications_open' OR now() NOT BETWEEN p.public_applications_open_at AND p.public_applications_close_at THEN RAISE EXCEPTION 'festival_sponsor_applications_closed' USING ERRCODE='P0001';END IF;IF pk.status<>'active' OR (p_payload->>'proposedCashMinor')::bigint<pk.minimum_cash_minor OR 10000*ink>pk.maximum_in_kind_share_basis_points*((p_payload->>'proposedCashMinor')::bigint+ink) THEN RAISE EXCEPTION 'festival_sponsor_company_ineligible' USING ERRCODE='P0001';END IF;PERFORM public._festival_sponsorship_validate_inventory(p.id,pk.id,(SELECT coalesce(jsonb_agg(jsonb_build_object('inventoryId',v,'quantity',1)),'[]') FROM unnest(coalesce(ARRAY(SELECT jsonb_array_elements_text(coalesce(p_payload->'requestedInventoryIds','[]'))::uuid),ARRAY[]::uuid[])) v));BEGIN INSERT INTO public.festival_sponsor_applications(festival_sponsorship_plan_id,package_id,company_id,submitted_by_profile_id,proposed_cash_minor,proposed_in_kind_minor,proposed_in_kind_items,requested_inventory_ids,message,company_quality_snapshot,company_reputation_snapshot,compatibility_snapshot) VALUES(p.id,pk.id,co,a,(p_payload->>'proposedCashMinor')::bigint,ink,coalesce(p_payload->'proposedInKindItems','[]'),coalesce(ARRAY(SELECT jsonb_array_elements_text(coalesce(p_payload->'requestedInventoryIds','[]'))::uuid),ARRAY[]::uuid[]),nullif(p_payload->>'message',''),50,50,jsonb_build_object('eligible',true,'capturedAt',now())) RETURNING * INTO x;EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'festival_sponsor_application_duplicate' USING ERRCODE='P0001';END;PERFORM public._festival_sponsorship_audit(q.id,c,'application',x.id,'application_submitted',NULL,'submitted',1);RETURN public._festival_sponsorship_finish_action(q.id,c,to_jsonb(x));END $$;
CREATE OR REPLACE FUNCTION public.withdraw_festival_sponsor_application(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();x public.festival_sponsor_applications%ROWTYPE;p public.festival_sponsorship_plans%ROWTYPE;q public.festival_sponsorship_requests%ROWTYPE;o text;BEGIN SELECT * INTO x FROM public.festival_sponsor_applications WHERE id=(p_payload->>'applicationId')::uuid FOR UPDATE;SELECT * INTO p FROM public.festival_sponsorship_plans WHERE id=x.festival_sponsorship_plan_id;IF NOT public._festival_sponsor_company_authorised(x.company_id,a) THEN RAISE EXCEPTION 'festival_sponsor_company_forbidden' USING ERRCODE='P0001';END IF;q:=public._festival_sponsorship_begin_action(p.festival_company_id,'withdraw_festival_sponsor_application',x.id,p_idempotency_key,p_payload);IF q.status='succeeded' THEN RETURN q.result;END IF;IF x.application_version<>(p_payload->>'expectedVersion')::int THEN RAISE EXCEPTION 'festival_sponsor_application_stale' USING ERRCODE='P0001';END IF;IF x.status NOT IN('submitted','under_review','shortlisted','proposal_pending') OR EXISTS(SELECT 1 FROM public.festival_sponsor_proposals z JOIN public.festival_sponsor_contracts k ON k.accepted_proposal_id=z.id WHERE z.application_id=x.id) THEN RAISE EXCEPTION 'festival_sponsor_application_invalid_transition' USING ERRCODE='P0001';END IF;o:=x.status;UPDATE public.festival_sponsor_applications SET status='withdrawn',withdrawn_at=now(),application_version=application_version+1 WHERE id=x.id RETURNING * INTO x;PERFORM public._festival_sponsorship_audit(q.id,p.festival_company_id,'application',x.id,'application_withdrawn',o,'withdrawn',x.application_version);RETURN public._festival_sponsorship_finish_action(q.id,p.festival_company_id,to_jsonb(x));END $$;
CREATE OR REPLACE FUNCTION public.review_festival_sponsor_application(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();x public.festival_sponsor_applications%ROWTYPE;p public.festival_sponsorship_plans%ROWTYPE;q public.festival_sponsorship_requests%ROWTYPE;n text;o text;BEGIN SELECT * INTO x FROM public.festival_sponsor_applications WHERE id=(p_payload->>'applicationId')::uuid FOR UPDATE;SELECT * INTO p FROM public.festival_sponsorship_plans WHERE id=x.festival_sponsorship_plan_id;IF NOT public._festival_sponsorship_authorised(p.festival_company_id,a) THEN RAISE EXCEPTION 'festival_sponsorship_forbidden' USING ERRCODE='P0001';END IF;q:=public._festival_sponsorship_begin_action(p.festival_company_id,'review_festival_sponsor_application',x.id,p_idempotency_key,p_payload);IF q.status='succeeded' THEN RETURN q.result;END IF;n:=CASE p_payload->>'decision' WHEN 'mark_under_review' THEN 'under_review' WHEN 'shortlist' THEN 'shortlisted' WHEN 'reject' THEN 'rejected' WHEN 'create_proposal' THEN 'proposal_pending' END;IF x.application_version<>(p_payload->>'expectedVersion')::int THEN RAISE EXCEPTION 'festival_sponsor_application_stale' USING ERRCODE='P0001';END IF;IF n IS NULL OR (x.status,n) NOT IN(('submitted','under_review'),('submitted','shortlisted'),('under_review','shortlisted'),('submitted','rejected'),('under_review','rejected'),('shortlisted','rejected'),('shortlisted','proposal_pending')) THEN RAISE EXCEPTION 'festival_sponsor_application_invalid_transition' USING ERRCODE='P0001';END IF;o:=x.status;UPDATE public.festival_sponsor_applications SET status=n,reviewed_at=now(),application_version=application_version+1 WHERE id=x.id RETURNING * INTO x;IF n='rejected' THEN INSERT INTO public.festival_sponsor_feedback(festival_sponsorship_plan_id,company_id,stage,reason_codes,message_key) VALUES(p.id,x.company_id,'application',coalesce(ARRAY(SELECT jsonb_array_elements_text(coalesce(p_payload->'reasonCodes','[]'))),ARRAY['package_mismatch']),'festival_sponsor_application_rejected');END IF;PERFORM public._festival_sponsorship_audit(q.id,p.festival_company_id,'application',x.id,'application_'||n,o,n,x.application_version,jsonb_build_object('internalNotes',p_payload->>'internalNotes'));RETURN public._festival_sponsorship_finish_action(q.id,p.festival_company_id,to_jsonb(x));END $$;

CREATE OR REPLACE FUNCTION public.send_festival_sponsor_invitation(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();c uuid:=(p_payload->>'festivalCompanyId')::uuid;p public.festival_sponsorship_plans%ROWTYPE;x public.festival_sponsor_invitations%ROWTYPE;q public.festival_sponsorship_requests%ROWTYPE;s text:=p_payload->>'sponsorSource';co uuid:=nullif(p_payload->>'companyId','')::uuid;n uuid:=nullif(p_payload->>'npcSponsorId','')::uuid;ad uuid:=nullif(p_payload->>'adminSponsorId','')::uuid;BEGIN SELECT * INTO p FROM public.festival_sponsorship_plans WHERE festival_company_id=c;IF NOT public._festival_sponsorship_authorised(c,a) THEN RAISE EXCEPTION 'festival_sponsorship_forbidden' USING ERRCODE='P0001';END IF;q:=public._festival_sponsorship_begin_action(c,'send_festival_sponsor_invitation',coalesce(co,n,ad),p_idempotency_key,p_payload);IF q.status='succeeded' THEN RETURN q.result;END IF;IF num_nonnulls(co,n,ad)<>1 OR s NOT IN('player_company','npc_company','admin_sponsor') OR (s='player_company')<>(co IS NOT NULL) OR NOT EXISTS(SELECT 1 FROM public.festival_sponsorship_packages k WHERE k.id=(p_payload->>'packageId')::uuid AND k.festival_sponsorship_plan_id=p.id AND k.status='active') OR (p_payload->>'expiresAt')::timestamptz<=now()+interval '1 hour' THEN RAISE EXCEPTION 'festival_sponsor_invitation_invalid' USING ERRCODE='P0001';END IF;BEGIN INSERT INTO public.festival_sponsor_invitations(festival_sponsorship_plan_id,package_id,company_id,npc_sponsor_id,admin_sponsor_id,sponsor_source,invited_by_profile_id,status,suggested_cash_minor,suggested_in_kind_minor,suggested_inventory_ids,message,expires_at) VALUES(p.id,(p_payload->>'packageId')::uuid,co,n,ad,s,a,'sent',coalesce((p_payload->>'suggestedCashMinor')::bigint,0),coalesce((p_payload->>'suggestedInKindMinor')::bigint,0),coalesce(ARRAY(SELECT jsonb_array_elements_text(coalesce(p_payload->'suggestedInventoryIds','[]'))::uuid),ARRAY[]::uuid[]),nullif(p_payload->>'message',''),(p_payload->>'expiresAt')::timestamptz) RETURNING * INTO x;EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'festival_sponsor_invitation_duplicate' USING ERRCODE='P0001';END;PERFORM public._festival_sponsorship_audit(q.id,c,'invitation',x.id,'invitation_sent',NULL,'sent',1);RETURN public._festival_sponsorship_finish_action(q.id,c,to_jsonb(x));END $$;
CREATE OR REPLACE FUNCTION public.respond_to_festival_sponsor_invitation(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();x public.festival_sponsor_invitations%ROWTYPE;p public.festival_sponsorship_plans%ROWTYPE;q public.festival_sponsorship_requests%ROWTYPE;n text:=p_payload->>'response';BEGIN SELECT * INTO x FROM public.festival_sponsor_invitations WHERE id=(p_payload->>'invitationId')::uuid FOR UPDATE;SELECT * INTO p FROM public.festival_sponsorship_plans WHERE id=x.festival_sponsorship_plan_id;IF x.sponsor_source='player_company' AND NOT public._festival_sponsor_company_authorised(x.company_id,a) THEN RAISE EXCEPTION 'festival_sponsor_company_forbidden' USING ERRCODE='P0001';END IF;IF x.sponsor_source<>'player_company' AND NOT public._festival_sponsorship_authorised(p.festival_company_id,a) THEN RAISE EXCEPTION 'festival_sponsorship_forbidden' USING ERRCODE='P0001';END IF;q:=public._festival_sponsorship_begin_action(p.festival_company_id,'respond_to_festival_sponsor_invitation',x.id,p_idempotency_key,p_payload);IF q.status='succeeded' THEN RETURN q.result;END IF;IF x.invitation_version<>(p_payload->>'expectedVersion')::int THEN RAISE EXCEPTION 'festival_sponsor_invitation_stale' USING ERRCODE='P0001';END IF;IF x.status NOT IN('sent','viewed') OR x.expires_at<=now() OR n NOT IN('interested','declined') THEN RAISE EXCEPTION 'festival_sponsor_invitation_expired' USING ERRCODE='P0001';END IF;UPDATE public.festival_sponsor_invitations SET status=n,responded_at=now(),invitation_version=invitation_version+1 WHERE id=x.id RETURNING * INTO x;IF n='declined' THEN INSERT INTO public.festival_sponsor_feedback(festival_sponsorship_plan_id,company_id,npc_sponsor_id,admin_sponsor_id,stage,reason_codes,message_key) VALUES(p.id,x.company_id,x.npc_sponsor_id,x.admin_sponsor_id,'invitation',ARRAY['package_mismatch'],'festival_sponsor_invitation_declined');END IF;PERFORM public._festival_sponsorship_audit(q.id,p.festival_company_id,'invitation',x.id,'invitation_'||n,'sent',n,x.invitation_version);RETURN public._festival_sponsorship_finish_action(q.id,p.festival_company_id,to_jsonb(x));END $$;

CREATE OR REPLACE FUNCTION public.create_festival_sponsor_proposal(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();c uuid:=(p_payload->>'festivalCompanyId')::uuid;p public.festival_sponsorship_plans%ROWTYPE;x public.festival_sponsor_proposals%ROWTYPE;r public.festival_sponsor_proposal_revisions%ROWTYPE;q public.festival_sponsorship_requests%ROWTYPE;co uuid:=nullif(p_payload->>'companyId','')::uuid;n uuid:=nullif(p_payload->>'npcSponsorId','')::uuid;ad uuid:=nullif(p_payload->>'adminSponsorId','')::uuid;s text:=p_payload->>'sponsorSource';BEGIN SELECT * INTO p FROM public.festival_sponsorship_plans WHERE festival_company_id=c FOR UPDATE;IF NOT public._festival_sponsorship_authorised(c,a) THEN RAISE EXCEPTION 'festival_sponsorship_forbidden' USING ERRCODE='P0001';END IF;q:=public._festival_sponsorship_begin_action(c,'create_festival_sponsor_proposal',coalesce(nullif(p_payload->>'applicationId','')::uuid,nullif(p_payload->>'invitationId','')::uuid,nullif(p_payload->>'prospectId','')::uuid,co,n,ad),p_idempotency_key,p_payload);IF q.status='succeeded' THEN RETURN q.result;END IF;IF num_nonnulls(co,n,ad)<>1 OR s NOT IN('player_company','npc_company','admin_sponsor') OR NOT EXISTS(SELECT 1 FROM public.festival_sponsorship_packages k WHERE k.id=(p_payload->>'packageId')::uuid AND k.festival_sponsorship_plan_id=p.id AND k.status='active') THEN RAISE EXCEPTION 'festival_sponsor_proposal_invalid' USING ERRCODE='P0001';END IF;IF nullif(p_payload->>'applicationId','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.festival_sponsor_applications z WHERE z.id=(p_payload->>'applicationId')::uuid AND z.company_id=co AND z.festival_sponsorship_plan_id=p.id) THEN RAISE EXCEPTION 'festival_sponsor_proposal_identity_mismatch' USING ERRCODE='P0001';END IF;PERFORM public._festival_sponsorship_validate_inventory(p.id,(p_payload->>'packageId')::uuid,coalesce(p_payload->'inventoryAllocations','[]'));PERFORM public._festival_sponsorship_validate_exclusivity(p.id,'00000000-0000-0000-0000-000000000000',coalesce(p_payload->'exclusivity','{}'));INSERT INTO public.festival_sponsor_proposals(festival_sponsorship_plan_id,application_id,invitation_id,prospect_id,sponsor_source,company_id,npc_sponsor_id,admin_sponsor_id,package_id,cash_contribution_minor,in_kind_contribution_minor,currency_code,exclusivity_category,exclusivity_scope,starts_at,ends_at,response_deadline,created_by_profile_id) VALUES(p.id,nullif(p_payload->>'applicationId','')::uuid,nullif(p_payload->>'invitationId','')::uuid,nullif(p_payload->>'prospectId','')::uuid,s,co,n,ad,(p_payload->>'packageId')::uuid,(p_payload->>'cashContributionMinor')::bigint,0,p.currency_code,p_payload->'exclusivity'->>'category',p_payload->'exclusivity'->>'scope',nullif(p_payload->>'startsAt','')::timestamptz,nullif(p_payload->>'endsAt','')::timestamptz,(p_payload->>'responseDeadline')::timestamptz,a) RETURNING * INTO x;INSERT INTO public.festival_sponsor_proposal_revisions(proposal_id,proposal_version,proposed_by_party,proposed_by_profile_id,cash_contribution_minor,in_kind_contribution_minor,in_kind_snapshot,inventory_snapshot,deliverables_snapshot,exclusivity_snapshot,terms_snapshot,response_deadline,message) VALUES(x.id,1,'festival',a,x.cash_contribution_minor,0,coalesce(p_payload->'inKindContributions','[]'),coalesce(p_payload->'inventoryAllocations','[]'),coalesce(p_payload->'deliverables','[]'),p_payload->'exclusivity',coalesce(p_payload->'terms','{}'),x.response_deadline,p_payload->>'message') RETURNING * INTO r;UPDATE public.festival_sponsor_proposals SET current_revision_id=r.id WHERE id=x.id RETURNING * INTO x;PERFORM public._festival_sponsorship_audit(q.id,c,'proposal',x.id,'proposal_created',NULL,'draft',1);RETURN public._festival_sponsorship_finish_action(q.id,c,jsonb_build_object('proposal',to_jsonb(x),'revision',to_jsonb(r)));END $$;
CREATE OR REPLACE FUNCTION public.send_festival_sponsor_proposal(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();x public.festival_sponsor_proposals%ROWTYPE;r public.festival_sponsor_proposal_revisions%ROWTYPE;p public.festival_sponsorship_plans%ROWTYPE;q public.festival_sponsorship_requests%ROWTYPE;BEGIN SELECT * INTO x FROM public.festival_sponsor_proposals WHERE id=(p_payload->>'proposalId')::uuid FOR UPDATE;SELECT * INTO p FROM public.festival_sponsorship_plans WHERE id=x.festival_sponsorship_plan_id FOR UPDATE;SELECT * INTO r FROM public.festival_sponsor_proposal_revisions WHERE id=x.current_revision_id;IF NOT public._festival_sponsorship_authorised(p.festival_company_id,a) THEN RAISE EXCEPTION 'festival_sponsorship_forbidden' USING ERRCODE='P0001';END IF;q:=public._festival_sponsorship_begin_action(p.festival_company_id,'send_festival_sponsor_proposal',x.id,p_idempotency_key,p_payload);IF q.status='succeeded' THEN RETURN q.result;END IF;IF x.proposal_version<>(p_payload->>'expectedVersion')::int THEN RAISE EXCEPTION 'festival_sponsor_proposal_stale' USING ERRCODE='P0001';END IF;IF x.status NOT IN('draft','countered') OR r.response_deadline<=now() THEN RAISE EXCEPTION 'festival_sponsor_proposal_expired' USING ERRCODE='P0001';END IF;PERFORM public._festival_sponsorship_validate_inventory(p.id,x.package_id,r.inventory_snapshot);PERFORM public._festival_sponsorship_validate_exclusivity(p.id,x.id,coalesce(r.exclusivity_snapshot,'{}'));UPDATE public.festival_sponsor_proposals SET status='sent',proposal_version=proposal_version+1,updated_at=now() WHERE id=x.id RETURNING * INTO x;PERFORM public._festival_sponsorship_audit(q.id,p.festival_company_id,'proposal',x.id,'proposal_sent','draft','sent',x.proposal_version);RETURN public._festival_sponsorship_finish_action(q.id,p.festival_company_id,to_jsonb(x));END $$;
CREATE OR REPLACE FUNCTION public.counter_festival_sponsor_proposal(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();x public.festival_sponsor_proposals%ROWTYPE;r public.festival_sponsor_proposal_revisions%ROWTYPE;p public.festival_sponsorship_plans%ROWTYPE;q public.festival_sponsorship_requests%ROWTYPE;BEGIN SELECT * INTO x FROM public.festival_sponsor_proposals WHERE id=(p_payload->>'proposalId')::uuid FOR UPDATE;SELECT * INTO p FROM public.festival_sponsorship_plans WHERE id=x.festival_sponsorship_plan_id;IF x.sponsor_source='player_company' AND NOT public._festival_sponsor_company_authorised(x.company_id,a) THEN RAISE EXCEPTION 'festival_sponsor_company_forbidden' USING ERRCODE='P0001';END IF;IF x.sponsor_source<>'player_company' THEN RAISE EXCEPTION 'festival_sponsorship_forbidden' USING ERRCODE='P0001';END IF;q:=public._festival_sponsorship_begin_action(p.festival_company_id,'counter_festival_sponsor_proposal',x.id,p_idempotency_key,p_payload);IF q.status='succeeded' THEN RETURN q.result;END IF;IF x.proposal_version<>(p_payload->>'expectedVersion')::int OR x.status<>'sent' OR x.response_deadline<=now() THEN RAISE EXCEPTION 'festival_sponsor_proposal_stale' USING ERRCODE='P0001';END IF;PERFORM public._festival_sponsorship_validate_inventory(p.id,x.package_id,coalesce(p_payload->'inventoryAllocations','[]'));PERFORM public._festival_sponsorship_validate_exclusivity(p.id,x.id,coalesce(p_payload->'exclusivity','{}'));INSERT INTO public.festival_sponsor_proposal_revisions(proposal_id,proposal_version,proposed_by_party,proposed_by_profile_id,cash_contribution_minor,in_kind_contribution_minor,in_kind_snapshot,inventory_snapshot,deliverables_snapshot,exclusivity_snapshot,terms_snapshot,response_deadline,message) VALUES(x.id,x.proposal_version+1,'sponsor',a,(p_payload->>'cashContributionMinor')::bigint,0,coalesce(p_payload->'inKindContributions','[]'),coalesce(p_payload->'inventoryAllocations','[]'),coalesce(p_payload->'deliverables','[]'),p_payload->'exclusivity',coalesce(p_payload->'terms','{}'),x.response_deadline,p_payload->>'message') RETURNING * INTO r;UPDATE public.festival_sponsor_proposals SET status='countered',cash_contribution_minor=r.cash_contribution_minor,in_kind_contribution_minor=r.in_kind_contribution_minor,current_revision_id=r.id,proposal_version=r.proposal_version,updated_at=now() WHERE id=x.id RETURNING * INTO x;PERFORM public._festival_sponsorship_audit(q.id,p.festival_company_id,'proposal',x.id,'proposal_countered','sent','countered',x.proposal_version);RETURN public._festival_sponsorship_finish_action(q.id,p.festival_company_id,jsonb_build_object('proposal',to_jsonb(x),'revision',to_jsonb(r)));END $$;

CREATE OR REPLACE FUNCTION public.respond_to_festival_sponsor_proposal(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();x public.festival_sponsor_proposals%ROWTYPE;r public.festival_sponsor_proposal_revisions%ROWTYPE;p public.festival_sponsorship_plans%ROWTYPE;k public.festival_sponsor_contracts%ROWTYPE;q public.festival_sponsorship_requests%ROWTYPE;act text:=p_payload->>'action';it jsonb;inv public.festival_sponsorship_inventory%ROWTYPE;qty int;BEGIN SELECT * INTO x FROM public.festival_sponsor_proposals WHERE id=(p_payload->>'proposalId')::uuid FOR UPDATE;SELECT * INTO p FROM public.festival_sponsorship_plans WHERE id=x.festival_sponsorship_plan_id FOR UPDATE;SELECT * INTO r FROM public.festival_sponsor_proposal_revisions WHERE id=x.current_revision_id FOR UPDATE;IF (x.status='sent' AND x.sponsor_source='player_company' AND NOT public._festival_sponsor_company_authorised(x.company_id,a)) OR (x.status='countered' AND NOT public._festival_sponsorship_authorised(p.festival_company_id,a)) THEN RAISE EXCEPTION 'festival_sponsorship_forbidden' USING ERRCODE='P0001';END IF;q:=public._festival_sponsorship_begin_action(p.festival_company_id,'respond_to_festival_sponsor_proposal',x.id,p_idempotency_key,p_payload);IF q.status='succeeded' THEN RETURN q.result;END IF;IF x.proposal_version<>(p_payload->>'expectedVersion')::int THEN RAISE EXCEPTION 'festival_sponsor_proposal_stale' USING ERRCODE='P0001';END IF;IF act NOT IN('accept','decline') OR x.status NOT IN('sent','countered') OR x.response_deadline<=now() THEN RAISE EXCEPTION 'festival_sponsor_proposal_expired' USING ERRCODE='P0001';END IF;IF act='decline' THEN UPDATE public.festival_sponsor_proposals SET status='declined',declined_at=now(),proposal_version=proposal_version+1,updated_at=now() WHERE id=x.id RETURNING * INTO x;INSERT INTO public.festival_sponsor_feedback(festival_sponsorship_plan_id,company_id,npc_sponsor_id,admin_sponsor_id,stage,reason_codes,message_key) VALUES(p.id,x.company_id,x.npc_sponsor_id,x.admin_sponsor_id,'proposal',ARRAY['package_mismatch'],'festival_sponsor_proposal_declined');PERFORM public._festival_sponsorship_audit(q.id,p.festival_company_id,'proposal',x.id,'proposal_declined',NULL,'declined',x.proposal_version);RETURN public._festival_sponsorship_finish_action(q.id,p.festival_company_id,to_jsonb(x));END IF;PERFORM public._festival_sponsorship_validate_inventory(p.id,x.package_id,r.inventory_snapshot);PERFORM public._festival_sponsorship_validate_exclusivity(p.id,x.id,coalesce(r.exclusivity_snapshot,'{}'));IF x.sponsor_source='player_company' AND coalesce((p_payload->>'financialCapacityVerified')::boolean,false)=false THEN RAISE EXCEPTION 'festival_sponsor_company_contribution_unaffordable' USING ERRCODE='P0001';END IF;UPDATE public.festival_sponsor_proposals SET status='accepted',accepted_at=now(),proposal_version=proposal_version+1,updated_at=now() WHERE id=x.id RETURNING * INTO x;INSERT INTO public.festival_sponsor_contracts(festival_sponsorship_plan_id,accepted_proposal_id,sponsor_source,company_id,npc_sponsor_id,admin_sponsor_id,package_id,cash_contribution_minor,in_kind_contribution_minor,total_contribution_minor,currency_code,terms_snapshot,exclusivity_snapshot) VALUES(p.id,x.id,x.sponsor_source,x.company_id,x.npc_sponsor_id,x.admin_sponsor_id,x.package_id,r.cash_contribution_minor,r.in_kind_contribution_minor,r.cash_contribution_minor+r.in_kind_contribution_minor,p.currency_code,r.terms_snapshot,r.exclusivity_snapshot) ON CONFLICT(accepted_proposal_id) DO UPDATE SET updated_at=public.festival_sponsor_contracts.updated_at RETURNING * INTO k;FOR it IN SELECT * FROM jsonb_array_elements(r.inventory_snapshot) LOOP qty:=coalesce((it->>'quantity')::int,1);SELECT * INTO inv FROM public.festival_sponsorship_inventory WHERE id=(it->>'inventoryId')::uuid FOR UPDATE;UPDATE public.festival_sponsorship_inventory SET quantity_contracted=quantity_contracted+qty,status=CASE WHEN quantity_contracted+qty=quantity_total THEN 'contracted' ELSE status END,inventory_version=inventory_version+1,updated_at=now() WHERE id=inv.id;INSERT INTO public.festival_branding_placements(sponsor_contract_id,inventory_id,placement_type,stage_id,ticket_product_id,quantity,exclusivity_key,visibility_score) VALUES(k.id,inv.id,inv.inventory_type,inv.stage_id,inv.ticket_product_id,qty,r.exclusivity_snapshot->>'key',inv.visibility_score) ON CONFLICT(sponsor_contract_id,inventory_id) DO NOTHING;END LOOP;FOR it IN SELECT * FROM jsonb_array_elements(r.deliverables_snapshot) LOOP INSERT INTO public.festival_sponsor_deliverables(sponsor_contract_id,deliverable_type,description,quantity,due_at,verification_method) VALUES(k.id,it->>'type',it->>'description',greatest(1,coalesce((it->>'quantity')::int,1)),nullif(it->>'dueAt','')::timestamptz,it->>'verificationMethod');END LOOP;IF NOT EXISTS(SELECT 1 FROM public.festival_sponsor_deliverables WHERE sponsor_contract_id=k.id) THEN INSERT INTO public.festival_sponsor_deliverables(sponsor_contract_id,deliverable_type,description,quantity) VALUES(k.id,'contract_acknowledgement','Planned sponsorship acknowledgement',1);END IF;INSERT INTO public.festival_financial_receivables(festival_company_id,sponsor_contract_id,source_type,amount_minor,currency_code,status,planned_due_at) VALUES(p.festival_company_id,k.id,'sponsor_contract_cash',k.cash_contribution_minor,p.currency_code,'planned',k.confirmed_at+interval '30 days') ON CONFLICT(sponsor_contract_id,source_type) DO NOTHING;IF k.in_kind_contribution_minor>0 THEN INSERT INTO public.festival_financial_receivables(festival_company_id,sponsor_contract_id,source_type,amount_minor,currency_code,status,contribution_category) VALUES(p.festival_company_id,k.id,'sponsor_contract_in_kind',k.in_kind_contribution_minor,p.currency_code,'planned','contracted_in_kind') ON CONFLICT(sponsor_contract_id,source_type) DO NOTHING;END IF;IF k.company_id IS NOT NULL THEN INSERT INTO public.festival_sponsor_company_commitments(company_id,sponsor_contract_id,amount_minor,currency_code) VALUES(k.company_id,k.id,k.cash_contribution_minor,p.currency_code) ON CONFLICT(sponsor_contract_id) DO NOTHING;END IF;UPDATE public.festival_sponsor_proposal_revisions SET proposed_by_party=proposed_by_party WHERE id=r.id;UPDATE public.festival_sponsor_applications SET status='proposal_pending' WHERE id=x.application_id;UPDATE public.festival_sponsor_invitations SET status='converted_to_proposal' WHERE id=x.invitation_id;UPDATE public.festival_sponsor_prospects SET status='contracted',updated_at=now() WHERE id=x.prospect_id;UPDATE public.festival_sponsorship_plans SET status='contracts_in_progress',planning_version=planning_version+1,updated_at=now() WHERE id=p.id;PERFORM public._festival_sponsorship_audit(q.id,p.festival_company_id,'contract',k.id,'contract_created',NULL,'committed',1,jsonb_build_object('paymentTransferred',false,'revenueRecognised',false));RETURN public._festival_sponsorship_finish_action(q.id,p.festival_company_id,jsonb_build_object('proposal',to_jsonb(x),'contract',to_jsonb(k),'finance',jsonb_build_object('cashTransferred',false,'revenueRecognised',false,'commitmentEstablished',k.company_id IS NOT NULL),'message','This agreement creates commercial commitments and planned sponsorship receivables. No money has been transferred yet.'));END $$;
CREATE OR REPLACE FUNCTION public.withdraw_festival_sponsor_proposal(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();x public.festival_sponsor_proposals%ROWTYPE;p public.festival_sponsorship_plans%ROWTYPE;q public.festival_sponsorship_requests%ROWTYPE;BEGIN SELECT * INTO x FROM public.festival_sponsor_proposals WHERE id=(p_payload->>'proposalId')::uuid FOR UPDATE;SELECT * INTO p FROM public.festival_sponsorship_plans WHERE id=x.festival_sponsorship_plan_id;IF NOT public._festival_sponsorship_authorised(p.festival_company_id,a) AND NOT (x.company_id IS NOT NULL AND public._festival_sponsor_company_authorised(x.company_id,a)) THEN RAISE EXCEPTION 'festival_sponsorship_forbidden' USING ERRCODE='P0001';END IF;q:=public._festival_sponsorship_begin_action(p.festival_company_id,'withdraw_festival_sponsor_proposal',x.id,p_idempotency_key,p_payload);IF q.status='succeeded' THEN RETURN q.result;END IF;IF x.proposal_version<>(p_payload->>'expectedVersion')::int THEN RAISE EXCEPTION 'festival_sponsor_proposal_stale' USING ERRCODE='P0001';END IF;IF x.status NOT IN('draft','sent','countered') THEN RAISE EXCEPTION 'festival_sponsor_proposal_invalid_transition' USING ERRCODE='P0001';END IF;UPDATE public.festival_sponsor_proposals SET status='withdrawn',withdrawn_at=now(),proposal_version=proposal_version+1,updated_at=now() WHERE id=x.id RETURNING * INTO x;PERFORM public._festival_sponsorship_audit(q.id,p.festival_company_id,'proposal',x.id,'proposal_withdrawn',NULL,'withdrawn',x.proposal_version);RETURN public._festival_sponsorship_finish_action(q.id,p.festival_company_id,to_jsonb(x));END $$;
CREATE OR REPLACE FUNCTION public.cancel_festival_sponsor_contract(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();k public.festival_sponsor_contracts%ROWTYPE;p public.festival_sponsorship_plans%ROWTYPE;q public.festival_sponsorship_requests%ROWTYPE;b public.festival_branding_placements%ROWTYPE;BEGIN SELECT * INTO k FROM public.festival_sponsor_contracts WHERE id=(p_payload->>'contractId')::uuid FOR UPDATE;SELECT * INTO p FROM public.festival_sponsorship_plans WHERE id=k.festival_sponsorship_plan_id FOR UPDATE;IF NOT public._festival_sponsorship_authorised(p.festival_company_id,a) AND NOT(k.company_id IS NOT NULL AND public._festival_sponsor_company_authorised(k.company_id,a)) THEN RAISE EXCEPTION 'festival_sponsorship_forbidden' USING ERRCODE='P0001';END IF;q:=public._festival_sponsorship_begin_action(p.festival_company_id,'cancel_festival_sponsor_contract',k.id,p_idempotency_key,p_payload);IF q.status='succeeded' THEN RETURN q.result;END IF;IF k.contract_version<>(p_payload->>'expectedVersion')::int THEN RAISE EXCEPTION 'festival_sponsor_contract_stale' USING ERRCODE='P0001';END IF;IF k.status NOT IN('committed','awaiting_activation') OR length(btrim(coalesce(p_payload->>'reason','')))<3 THEN RAISE EXCEPTION 'festival_sponsor_contract_not_cancellable' USING ERRCODE='P0001';END IF;FOR b IN SELECT * FROM public.festival_branding_placements WHERE sponsor_contract_id=k.id AND status<>'cancelled' FOR UPDATE LOOP UPDATE public.festival_sponsorship_inventory SET quantity_contracted=greatest(0,quantity_contracted-b.quantity),status='available',inventory_version=inventory_version+1,updated_at=now() WHERE id=b.inventory_id;END LOOP;UPDATE public.festival_sponsor_contracts SET status='cancelled',cancelled_at=now(),contract_version=contract_version+1,updated_at=now() WHERE id=k.id RETURNING * INTO k;UPDATE public.festival_branding_placements SET status='cancelled',updated_at=now() WHERE sponsor_contract_id=k.id;UPDATE public.festival_sponsor_deliverables SET status='cancelled',updated_at=now() WHERE sponsor_contract_id=k.id AND status<>'cancelled';UPDATE public.festival_sponsor_contributions SET status='cancelled',updated_at=now() WHERE sponsor_contract_id=k.id;UPDATE public.festival_financial_receivables SET status='cancelled',cancelled_at=now() WHERE sponsor_contract_id=k.id AND status='planned';UPDATE public.festival_sponsor_company_commitments SET status='released',released_at=now() WHERE sponsor_contract_id=k.id AND status='reserved';UPDATE public.festival_sponsorship_plans SET planning_version=planning_version+1,status='contracts_in_progress',updated_at=now() WHERE id=p.id;INSERT INTO public.festival_sponsor_feedback(festival_sponsorship_plan_id,company_id,npc_sponsor_id,admin_sponsor_id,stage,reason_codes,message_key,safe_metadata) VALUES(p.id,k.company_id,k.npc_sponsor_id,k.admin_sponsor_id,'contract',ARRAY['package_mismatch'],'festival_sponsor_contract_cancelled',jsonb_build_object('reason',left(p_payload->>'reason',240)));PERFORM public._festival_sponsorship_audit(q.id,p.festival_company_id,'contract',k.id,'contract_cancelled',NULL,'cancelled',k.contract_version);RETURN public._festival_sponsorship_finish_action(q.id,p.festival_company_id,to_jsonb(k));END $$;
CREATE OR REPLACE FUNCTION public.refresh_festival_npc_sponsor_prospects(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();c uuid:=(p_payload->>'festivalCompanyId')::uuid;p public.festival_sponsorship_plans%ROWTYPE;q public.festival_sponsorship_requests%ROWTYPE;n int:=least(10,greatest(1,coalesce((p_payload->>'limit')::int,5)));i int;seed uuid;items jsonb:='[]';BEGIN SELECT * INTO p FROM public.festival_sponsorship_plans WHERE festival_company_id=c FOR UPDATE;IF NOT public._festival_sponsorship_authorised(c,a) THEN RAISE EXCEPTION 'festival_sponsorship_forbidden' USING ERRCODE='P0001';END IF;q:=public._festival_sponsorship_begin_action(c,'refresh_festival_npc_sponsor_prospects',p.id,p_idempotency_key,p_payload);IF q.status='succeeded' THEN RETURN q.result;END IF;IF EXISTS(SELECT 1 FROM public.festival_sponsorship_audit WHERE festival_company_id=c AND event_type='npc_prospects_refreshed' AND created_at>now()-interval '24 hours') THEN RAISE EXCEPTION 'festival_sponsor_prospect_refresh_cooldown' USING ERRCODE='P0001';END IF;FOR i IN 1..n LOOP seed:=md5(p.id::text||date_trunc('day',now())::text||i::text)::uuid;INSERT INTO public.festival_sponsor_prospects(festival_sponsorship_plan_id,sponsor_source,npc_sponsor_id,compatibility_score,audience_fit_score,genre_fit_score,festival_fit_score,reputation_fit_score,commercial_capacity_score,community_value_score,relationship_score,risk_score) VALUES(p.id,'npc_company',seed,35+(i*7)%60,40+(i*11)%55,30+(i*13)%65,40+(i*17)%55,30+(i*19)%65,25+(i*23)%70,40+(i*29)%55,20+(i*31)%75,5+(i*7)%50) ON CONFLICT DO NOTHING;END LOOP;UPDATE public.festival_sponsorship_plans SET planning_version=planning_version+1,updated_at=now() WHERE id=p.id;PERFORM public._festival_sponsorship_audit(q.id,c,'sponsorship_plan',p.id,'npc_prospects_refreshed',NULL,NULL,p.planning_version+1,jsonb_build_object('count',n,'window',date_trunc('day',now())));RETURN public._festival_sponsorship_finish_action(q.id,c,jsonb_build_object('count',n,'bounded',true));END $$;
CREATE OR REPLACE FUNCTION public.search_festival_sponsor_prospects(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();c uuid:=(p_payload->>'festivalCompanyId')::uuid;p public.festival_sponsorship_plans%ROWTYPE;q public.festival_sponsorship_requests%ROWTYPE;o jsonb;BEGIN SELECT * INTO p FROM public.festival_sponsorship_plans WHERE festival_company_id=c;IF NOT public._festival_sponsorship_authorised(c,a) THEN RAISE EXCEPTION 'festival_sponsorship_forbidden' USING ERRCODE='P0001';END IF;q:=public._festival_sponsorship_begin_action(c,'search_festival_sponsor_prospects',p.id,p_idempotency_key,p_payload);IF q.status='succeeded' THEN RETURN q.result;END IF;SELECT coalesce(jsonb_agg(jsonb_build_object('id',x.id,'source',x.sponsor_source,'companyId',x.company_id,'npcSponsorId',x.npc_sponsor_id,'adminSponsorId',x.admin_sponsor_id,'compatibilityScore',x.compatibility_score,'audienceFit',x.audience_fit_score,'festivalFit',x.festival_fit_score,'commercialCapacityCategory',CASE WHEN x.commercial_capacity_score>=75 THEN 'strong_capacity' WHEN x.commercial_capacity_score>=50 THEN 'adequate_capacity' WHEN x.commercial_capacity_score>=25 THEN 'limited_capacity' ELSE 'insufficient_capacity' END,'relationshipScore',x.relationship_score,'riskFlags',x.risk_flags,'status',x.status)),'[]') INTO o FROM (SELECT * FROM public.festival_sponsor_prospects WHERE festival_sponsorship_plan_id=p.id AND (coalesce(p_payload->>'source','')='' OR sponsor_source=p_payload->>'source') ORDER BY compatibility_score DESC,id LIMIT least(100,greatest(1,coalesce((p_payload->>'limit')::int,25))) OFFSET greatest(0,coalesce((p_payload->>'offset')::int,0))) x;RETURN public._festival_sponsorship_finish_action(q.id,c,jsonb_build_object('items',o));END $$;

CREATE OR REPLACE FUNCTION public.get_available_festival_sponsorship_opportunities(p_filters jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ SELECT jsonb_build_object('items',coalesce(jsonb_agg(jsonb_build_object('festivalCompanyId',p.festival_company_id,'festivalName',cfg.public_name,'city',NULL,'country',NULL,'startDate',cfg.planned_start_date,'endDate',cfg.planned_end_date,'scale',cfg.festival_scale,'vibe',NULL,'festivalType','music','genreSummary','[]'::jsonb,'audienceSummary',jsonb_build_object('safeCategory','festival_audience'),'applicationDeadline',p.public_applications_close_at,'packages',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',x.id,'name',x.name,'tier',x.tier,'minimumCashMinor',x.minimum_cash_minor,'permittedInKindShareBasisPoints',x.maximum_in_kind_share_basis_points,'targetIndustries',x.target_industries,'excludedIndustries',x.excluded_industries)),'[]') FROM public.festival_sponsorship_packages x WHERE x.festival_sponsorship_plan_id=p.id AND x.status='active'),'inventorySummary',(SELECT coalesce(jsonb_agg(jsonb_build_object('type',i.inventory_type,'availableQuantity',i.quantity_total-i.quantity_reserved-i.quantity_contracted,'exclusive',i.exclusive)),'[]') FROM public.festival_sponsorship_inventory i WHERE i.festival_sponsorship_plan_id=p.id AND i.status<>'archived'),'eligibility',jsonb_build_object('canApply',auth.uid() IS NOT NULL,'reasonCodes','[]'::jsonb),'companyAuthority','unknown','affordabilityCategory','unknown','existingApplicationState',NULL,'existingInvitationState',NULL,'existingProposalState',NULL)) FILTER(WHERE p.id IS NOT NULL),'[]')) FROM public.festival_sponsorship_plans p JOIN public.festival_configurations cfg ON cfg.festival_company_id=p.festival_company_id WHERE p.status='applications_open' AND p.application_mode IN('applications_only','hybrid') AND now() BETWEEN p.public_applications_open_at AND p.public_applications_close_at AND (coalesce(p_filters->>'scale','')='' OR cfg.festival_scale=p_filters->>'scale') $$;

REVOKE ALL ON FUNCTION public._festival_sponsorship_begin_action(uuid,text,uuid,uuid,jsonb), public._festival_sponsorship_finish_action(uuid,uuid,jsonb), public._festival_sponsorship_audit(uuid,uuid,text,uuid,text,text,text,integer,jsonb), public._festival_sponsorship_validate_inventory(uuid,uuid,jsonb), public._festival_sponsorship_validate_exclusivity(uuid,uuid,jsonb), public._festival_sponsor_company_authorised(uuid,uuid), public._festival_sponsorship_authorised(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_available_festival_sponsorship_opportunities(jsonb),public.open_festival_sponsor_applications(jsonb,uuid),public.close_festival_sponsor_applications(jsonb,uuid),public.submit_festival_sponsor_application(jsonb,uuid),public.withdraw_festival_sponsor_application(jsonb,uuid),public.review_festival_sponsor_application(jsonb,uuid),public.send_festival_sponsor_invitation(jsonb,uuid),public.respond_to_festival_sponsor_invitation(jsonb,uuid),public.create_festival_sponsor_proposal(jsonb,uuid),public.send_festival_sponsor_proposal(jsonb,uuid),public.counter_festival_sponsor_proposal(jsonb,uuid),public.respond_to_festival_sponsor_proposal(jsonb,uuid),public.withdraw_festival_sponsor_proposal(jsonb,uuid),public.cancel_festival_sponsor_contract(jsonb,uuid),public.refresh_festival_npc_sponsor_prospects(jsonb,uuid),public.search_festival_sponsor_prospects(jsonb,uuid) TO authenticated;
